    return f'''<div class="resource"><div class="ring" style="--dash:{float(value)*3.644}"><svg viewBox="0 0 132 132"><circle class="track" cx="66" cy="66" r="58"/><circle class="progress" cx="66" cy="66" r="58"/></svg><div class="value">{value}<small>%</small></div></div><div class="label">{label}</div><div class="detail">{detail}</div></div>'''

